const b = ($input.first().json.body) || {};
const s = (v, n) => (v === undefined || v === null) ? null : String(v).slice(0, n);
const KINDS = ['onerror', 'unhandledrejection', 'boundary', 'api'];
const kind = KINDS.includes(b.kind) ? b.kind : 'onerror';
const stack_hash = (s(b.stack_hash, 8) || '').toLowerCase();
const session_id = (s(b.session_id, 36) || '').toLowerCase();
const message = (s(b.message, 500) || '').trim();
const V4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const valid = /^[0-9a-f]{8}$/.test(stack_hash) && V4.test(session_id) && message.length > 0;
const status = (b.status === undefined || b.status === null || b.status === '' || !Number.isFinite(Number(b.status))) ? null : Math.trunc(Number(b.status));
let client_time = null;
if (b.client_time) { const d = new Date(b.client_time); if (!isNaN(d.getTime())) client_time = d.toISOString().slice(0, 19).replace('T', ' '); }
return [{ json: { valid, kind, stack_hash, session_id, screen: s(b.screen, 50), endpoint: s(b.endpoint, 80), status, message, stack: s(b.stack, 2048), user_agent: s(b.user_agent, 255), app_version: s(b.app_version, 40), week_date_range: s(b.week_date_range, 80), client_time } }];
